{
  "tickets": [
    {
      "id": "gen-361",
      "subject": "Compliance archive and backup settings help",
      "body": "Hello, could you please help us set up our data backup schedules and retrieve an export of our historical data for our compliance audit? Thank you."
    },
    {
      "id": "gen-362",
      "subject": "Routing abnormal lab results to covering physicians",
      "body": "Hi support team, I'm trying to figure out the best way to handle incoming lab results when doctors are out of the office. Specifically, how do I route abnormal labs so that covering physicians can review, sign off, and annotate them before they get filed into the patient charts? I tried looking in the notification settings menu earlier today, but I couldn't find a clear option to delegate those queues. Let me know what steps I need to take. Thanks."
    },
    {
      "id": "gen-363",
      "subject": "URGENT: Portal credit card payments failing",
      "body": "Hello, I have patients sitting in the waiting room right now trying to pay their balances through the online portal, and every single credit card transaction is throwing an error on the payment screen. I've tried refreshing the page and clearing the browser cache, but it keeps declining valid cards. Please look into this immediately as our front desk is backed up trying to process these payments manually."
    },
    {
      "id": "gen-364",
      "subject": "Linking pharmacy renewal requests to active meds",
      "body": "How do we link electronic pharmacy refill renewal requests directly to a patient's active medication list when processing them? Right now it just creates a loose note instead of updating the chart properly. Please provide instructions."
    },
    {
      "id": "gen-365",
      "subject": "Data backup schedules and BAA documentation",
      "body": "Hello, we are updating our administrative records and need to verify our data backup frequency settings. Could you also point me to where we can download our signed business associate agreement and adjust our compliance archive parameters?"
    },
    {
      "id": "gen-366",
      "subject": "Questions regarding patient appointment reminders",
      "body": "Hi there, I am so sorry to bother you with this, but some of our patients have mentioned they aren't receiving their automated text and email reminders lately. Could someone help us check our reminder configurations and make sure the messaging service is running properly for our clinic? Thank you so much for your time and help."
    },
    {
      "id": "gen-367",
      "subject": "Restrict online booking visit types",
      "body": "How do we limit online portal booking to specific providers and routine visit types only? Please advise."
    },
    {
      "id": "gen-368",
      "subject": "Appointment reminder messages failing",
      "body": "Patients aren't receiving SMS reminders. Please check our settings."
    },
    {
      "id": "gen-369",
      "subject": "Pharmacy substitution messaging workflow help",
      "body": "Hello, I am sorry to reach out about this, but I wanted to make sure I am using the right steps for handling out-of-stock medication alerts. Could you please send over a quick guide on how to properly route pharmacy substitution requests and update alternative therapeutic agents in the system? Thank you for your patience and assistance."
    },
    {
      "id": "gen-370",
      "subject": "Updating card on file for subscription invoices",
      "body": "Hello, I am writing to see how we can update the credit card on file for our monthly software subscription. Our current card is expiring soon, and I'd like to swap it out before the next invoice generates. Could you let me know where to find that billing screen?"
    }
  ]
}
